public class MathArrays_sortInPlace_TriageGen0Test {

    @Test
    public void testSortInPlaceIncreasing() throws NullArgumentException, DimensionMismatchException {
        double[] x = {3.0, 1.0, 2.0};
        double[] y1 = {10.0, 30.0, 20.0};
        double[] y2 = {100.0, 300.0, 200.0};

        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y1, y2);

        assertArrayEquals(new double[]{1.0, 2.0, 3.0}, x, 1e-10);
        assertArrayEquals(new double[]{30.0, 20.0, 10.0}, y1, 1e-10);
        assertArrayEquals(new double[]{300.0, 200.0, 100.0}, y2, 1e-10);
    }

    @Test
    public void testSortInPlaceDecreasing() throws NullArgumentException, DimensionMismatchException {
        double[] x = {3.0, 1.0, 2.0};
        double[] y1 = {10.0, 30.0, 20.0};

        MathArrays.sortInPlace(x, MathArrays.OrderDirection.DECREASING, y1);

        assertArrayEquals(new double[]{3.0, 2.0, 1.0}, x, 1e-10);
        assertArrayEquals(new double[]{10.0, 20.0, 30.0}, y1, 1e-10);
    }

    @Test
    public void testSortInPlaceNoYList() throws NullArgumentException, DimensionMismatchException {
        double[] x = {3.0, 1.0, 2.0};
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING);
        assertArrayEquals(new double[]{1.0, 2.0, 3.0}, x, 1e-10);
    }

    @Test(expected = NullArgumentException.class)
    public void testSortInPlaceNullX() throws NullArgumentException, DimensionMismatchException {
        MathArrays.sortInPlace(null, MathArrays.OrderDirection.INCREASING);
    }

    @Test(expected = NullArgumentException.class)
    public void testSortInPlaceNullY() throws NullArgumentException, DimensionMismatchException {
        double[] x = {1.0, 2.0};
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, (double[]) null);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testSortInPlaceDimensionMismatch() throws NullArgumentException, DimensionMismatchException {
        double[] x = {1.0, 2.0, 3.0};
        double[] y = {1.0, 2.0}; // Length 2 != 3
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);
    }

    @Test
    public void testSortInPlaceDuplicateValues() throws NullArgumentException, DimensionMismatchException {
        double[] x = {2.0, 1.0, 2.0};
        double[] y = {10.0, 20.0, 30.0};
        // The sort is stable for the pairs, but the implementation uses Collections.sort on Pairs.
        // We just check if the resulting x is sorted and y values are associated correctly.
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);

        assertArrayEquals(new double[]{1.0, 2.0, 2.0}, x, 1e-10);
        // Since 2.0 appears at index 0 and 2, and they are sorted, 
        // the y values will be [20.0, 10.0, 30.0] or [20.0, 30.0, 10.0] depending on Pair stability.
        // However, the logic in the code uses Pair(x[i], i). 
        // For x[0]=2.0, index=0. For x[2]=2.0, index=2.
        // In increasing order, (1.0,1), (2.0,0), (2.0,2) OR (1.0,1), (2.0,2), (2.0,0).
        // Standard Collections.sort on these pairs will result in (1.0,1), (2.0,0), (2.0,2).
        assertArrayEquals(new double[]{20.0, 10.0, 30.0}, y, 1e-10);
    }

    @Test
    public void testSortInPlaceSingleElement() throws NullArgumentException, DimensionMismatchException {
        double[] x = {5.0};
        double[] y = {10.0};
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);
        assertArrayEquals(new double[]{5.0}, x, 1e-10);
        assertArrayEquals(new double[]{10.0}, y, 1e-10);
    }

    @Test
    public void testSortInPlaceEmptyArray() throws NullArgumentException, DimensionMismatchException {
        double[] x = {};
        double[] y = {};
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);
        assertArrayEquals(new double[]{}, x, 1e-10);
        assertArrayEquals(new double[]{}, y, 1e-10);
    }
}
